+    const events = await ctx.db
+      .query("event_ledger")
+      .withIndex("by_institution_seq", (q) => q.eq("institutionId", caller.institutionId))
+      .filter((q) => q.gte(q.field("seq"), fromSeq))
+      .order("asc")
+      .take(limit + 1);
