+    const verifiedCount = Math.min(events.length, limit);
+    return {
+      valid: true,
+      brokenAtSeq: undefined,
+      count: verifiedCount,
+      ...(events.length > limit ? { nextCursor: events[limit - 1].seq + 1 } : {}),
+    };
