+  let user: Doc<"users"> | null;
+  try {
+    user = await ctx.db.get(claims.userId as Id<"users">);
+  } catch {
+    throw new ConvexError("unauthorized");
+  }
+  if (user === null || user.status === "suspended") throw new ConvexError("unauthorized");
+  return user;
