+        />
+      </div>
+    );
+  }
+
+  return (
+    <div className="flex flex-col gap-6">
+      <PageHeader
+        eyebrow="Faculty panel"
+        title="Class sessions"
+        description="Start, monitor, and close your class sessions."
+      />
+      <ScheduleList actorToken={actorToken} initialRows={rows} />
+    </div>
+  );
+}

