+"use client";
+
+import { api } from "../../../../../convex/_generated/api";
+import { useMutation } from "convex/react";
+import { Loader2, ScanLine } from "lucide-react";
+import { useCallback, useEffect, useRef, useState } from "react";
+
+import { Badge } from "@/components/ui/badge";
+import { Button } from "@/components/ui/button";
+import {
+  Card,
+  CardAction,
+  CardContent,
+  CardDescription,
+  CardHeader,
+  CardTitle,
+} from "@/components/ui/card";
+import { Input } from "@/components/ui/input";
+
+import { OutcomeScreen, type CheckInOutcome } from "./outcome-screen";
+import { StepUpChallenge, type StepUpChallengeRef } from "./step-up-challenge";
+
+export type ActiveClassSession = {
+  sessionId: string;
+  courseCode: string;
+  courseTitle: string;
+  sectionName: string;
+  venueName: string;
+  windowEndsAt: number;
+};
+
+type StepUpOutcome = {
+  challenge: StepUpChallengeRef;
+  courseCode: string;
+  venueName: string;
+};
+
+type CameraState = "off" | "active" | "unavailable";
+
+type CameraUnavailableReason = "scanner_unsupported" | "camera_unavailable";
+
+type GeoFix = {
+  latitude: number;
+  longitude: number;
+  accuracyMeters?: number;
+  capturedAt?: number;
+};
+
+type GeoState = {
+  fix: GeoFix | null;
+  consent: "granted" | "denied" | "not_requested";
+  availability?: "ok" | "unavailable";
+};
+
+function geoStatusLabel(geo: GeoState | null): string {
+  if (geo === null) return "Location off";
+  if (geo.fix !== null) return "Location ready";
+  if (geo.consent === "denied" || geo.consent === "not_requested") return "Location off";
+  return "Location unavailable";
+}
+
+function formatCountdown(totalSeconds: number): string {
+  const minutes = Math.floor(totalSeconds / 60);
+  const seconds = totalSeconds % 60;
+  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
+}
+
+function useSecondsUntil(target: number): number | null {
+  const [secondsLeft, setSecondsLeft] = useState<number | null>(null);
+  useEffect(() => {
+    const tick = () => setSecondsLeft(Math.max(0, Math.ceil((target - Date.now()) / 1000)));
+    tick();
+    const timer = setInterval(tick, 1000);
+    return () => clearInterval(timer);
+  }, [target]);
+  return secondsLeft;
+}
+
+export function CheckInPanel({
+  actorToken,
+  active,
+}: {
+  actorToken: string;
+  active: ActiveClassSession | null;
+}) {
+  const redeemChallenge = useMutation(api.checkin.redeemChallenge);
+  const [outcome, setOutcome] = useState<CheckInOutcome | null>(null);
+  const [stepUp, setStepUp] = useState<StepUpOutcome | null>(null);
+  const [code, setCode] = useState("");
+  const [submitting, setSubmitting] = useState(false);
+  const [cameraState, setCameraState] = useState<CameraState>("off");
+  const [unavailableReason, setUnavailableReason] = useState<CameraUnavailableReason | null>(null);
+  const [pendingToken, setPendingToken] = useState<string | null>(null);
+  const [geo, setGeo] = useState<GeoState | null>(null);
+  const videoRef = useRef<HTMLVideoElement>(null);
+
+  useEffect(() => {
+    if (!("geolocation" in navigator)) {
+      setGeo({ fix: null, consent: "not_requested" });
+      return;
+    }
+    navigator.geolocation.getCurrentPosition(
+      (position) => {
+        setGeo({
+          fix: {
+            latitude: position.coords.latitude,
+            longitude: position.coords.longitude,
+            accuracyMeters: position.coords.accuracy,
+            capturedAt: position.timestamp,
+          },
+          consent: "granted",
+          availability: "ok",
+        });
+      },
+      (error) => {
+        if (error.code === 1) {
+          setGeo({ fix: null, consent: "denied" });
+        } else {
+          setGeo({ fix: null, consent: "granted", availability: "unavailable" });
+        }
+      },
+      { enableHighAccuracy: false, timeout: 8000, maximumAge: 30000 },
+    );
+  }, []);
+
+  const submit = useCallback(
+    async (token: string) => {
+      const trimmed = token.trim();
+      if (trimmed.length === 0 || submitting) return;
+      setSubmitting(true);
+      try {
+        const result = await redeemChallenge({
+          actorToken,
+          token: trimmed,
+          ...(geo !== null && geo.consent === "granted" && geo.fix !== null
+            ? { location: geo.fix }
+            : {}),
+          locationConsent: geo?.consent ?? "not_requested",
+          locationAvailability: geo?.availability ?? "ok",
+        });
+        if (result.kind === "ok") {
+          setOutcome({
+            kind: "success",
+            courseCode: result.courseCode,
+            venueName: result.venueName,
+            checkedInAt: result.checkedInAt,
+            decision: {
+              outcome: result.outcome,
+              evidence: result.evidence,
+              reasonCodes: result.reasonCodes,
+              policyVersion: result.policyVersion,
+              decidedAt: result.decidedAt,
+            },
+          });
+        } else if (result.kind === "step_up") {
+          setStepUp({
+            challenge: {
+              _id: result.challenge._id,
+              expiresAt: result.challenge.expiresAt,
+            },
+            courseCode: result.courseCode,
+            venueName: result.venueName,
+          });
+        } else if (result.kind === "rate_limited") {
+          setOutcome({ kind: "rate_limited", retryAfterSeconds: result.retryAfterSeconds });
+        } else {
+          setOutcome({
+            kind: "failure",
+            verdict: result.verdict,
+            reasonCodes: result.reasonCodes,
