+              data-testid="submit-code"
+              disabled={submitting || code.trim().length === 0}
+            >
+              {submitting ? <Loader2 className="animate-spin" /> : null}
+              Submit
+            </Button>
+          </form>
+        </CardContent>
+      </Card>
+    </div>
+  );
