+import {
+  DEFAULT_ATTENDANCE_THRESHOLD_PERCENT,
+  summarizeAttendance,
+} from "@/lib/attendance/projection";
+import { mintActorToken } from "@/lib/auth/actor-token";
+import { getActiveSession } from "@/lib/auth/server";
