+            <p className="max-w-sm text-sm font-medium">{projectionSentence}</p>
+          </section>
+          <HistoryViews
+            records={calendarRecords}
+            subjects={subjects}
+            thresholdPercent={thresholdPercent}
+          />
+        </>
+      )}
