+    const embedding = normalizeToEmbedding({ data, width: 64, height: 32 });
+    const cell = 0.299 / Math.sqrt(EMBEDDING_DIMS * 0.299 * 0.299);
+    embedding.forEach((value) => expect(value).toBeCloseTo(cell, 10));
+  });
+
