(() => {
  const banner = document.querySelector('[data-testid="demo-banner"]');
  const h1 = document.querySelector('h1')?.textContent;
  const skip = document.querySelector('a[href="#main-content"]');
  const order = skip && banner ? skip.compareDocumentPosition(banner) & Node.DOCUMENT_POSITION_FOLLOWING : null;
  return JSON.stringify({
    banner: banner ? banner.textContent.trim() : null,
    skipLinkFirst: order === Node.DOCUMENT_POSITION_FOLLOWING,
    h1,
    viewport: window.innerWidth + 'x' + window.innerHeight
  })
})()

(() => {
  const banner = document.querySelector('[data-testid="demo-banner"]');
  const personas = [...document.querySelectorAll('a[href*="dev-session"], button')].map(b => b.textContent.trim()).slice(0, 12);
  return JSON.stringify({ bannerOnLogin: !!banner, personas })
})()

(() => {
  const btn = document.querySelector('button[aria-controls="mobile-nav-menu"]');
  const heading = document.querySelector('h1')?.textContent;
  return JSON.stringify({
    url: location.pathname,
    heading,
    mobileNavBtn: !!btn,
    ariaExpanded: btn?.getAttribute('aria-expanded'),
    ariaLabel: btn?.getAttribute('aria-label'),
    roleLabel: document.querySelector('#mobile-nav-menu')?.textContent?.slice(0, 40) ?? null
  })
})()

(() => {
  const btn = document.querySelector('button[aria-controls="mobile-nav-menu"]');
  const menu = document.getElementById('mobile-nav-menu');
  const links = [...(menu?.querySelectorAll('a') || [])].map(a => a.getAttribute('aria-current') === 'page' ? a.textContent.trim() + '*' : a.textContent.trim());
  return JSON.stringify({
    ariaExpanded: btn?.getAttribute('aria-expanded'),
    ariaLabel: btn?.getAttribute('aria-label'),
    menuVisible: menu ? getComputedStyle(menu).display !== 'none' : false,
    links
  })
})()

(() => new Promise(res => setTimeout(() => {
  const btn = document.querySelector('button[aria-controls="mobile-nav-menu"]');
  const menu = document.getElementById('mobile-nav-menu');
  const unavailableMsg = [...document.querySelectorAll('p')].map(p => p.textContent).find(t => t.includes('paste the check-in code'));
  res(JSON.stringify({
    url: location.pathname,
    menuClosed: !menu,
    ariaExpanded: btn?.getAttribute('aria-expanded'),
    checkinHeading: document.querySelector('h1')?.textContent,
    cameraMsg: unavailableMsg?.trim().slice(0, 80) ?? null
  }))
}, 1200)))()

(() => {
  const startBtns = [...document.querySelectorAll('button')].filter(b => /start/i.test(b.textContent)).map(b => b.textContent.trim());
  const sessionLinks = [...document.querySelectorAll('a[href*="/faculty/sessions/"]')].map(a => a.getAttribute('href'));
  return JSON.stringify({ startBtns, sessionLinks, bodyText: document.body.innerText.slice(0, 200).replace(/\n+/g, ' | ') })
})()

(() => new Promise(res => setTimeout(() => {
  const wrap = document.querySelector('.max-h-\\[70vh\\]');
  const th = document.querySelector('thead th');
  res(JSON.stringify({
    url: location.pathname.slice(0, 40),
    hasRosterWrapper: !!wrap,
    wrapperClasses: wrap ? wrap.className.slice(0, 80) : null,
    thSticky: th ? getComputedStyle(th).position : null,
    thBg: th ? getComputedStyle(th).backgroundColor : null,
    qrVisible: !!document.querySelector('[data-testid="qr-token"]'),
    boardCounts: [...document.querySelectorAll('[data-testid^="board-count-"]')].map(b => b.textContent.trim())
  }))
}, 2500)))()

(() => {
  const aside = document.querySelector('aside');
  const label = [...document.querySelectorAll('aside p')].map(p => p.textContent).find(t => t.includes('panel'));
  const signOut = !!document.querySelector('aside button');
  return JSON.stringify({ desktopSidebar: !!aside, panelLabel: label, signOutPresent: signOut, bannerStillTop: !!document.querySelector('[data-testid="demo-banner"]') })
})()

(() => new Promise(res => setTimeout(() => {
  const corner = document.querySelector('a[href="/login?as=student"] span.font-mono');
  const flag = [...document.querySelectorAll('.text-verdict-flag')].at(-1);
  let ratio = null;
  if (flag) {
    const fg = getComputedStyle(flag).color, bg = getComputedStyle(flag.parentElement).backgroundColor;
    ratio = fg + ' on ' + bg;
  }
  res(JSON.stringify({
    banner: document.querySelector('[data-testid="demo-banner"]')?.textContent.trim().slice(0, 50),
    cornerNumber: corner?.textContent,
    cornerColor: corner ? getComputedStyle(corner).color : null,
    flagStampSample: ratio,
    demoFeedHidden: document.querySelector('[data-testid="demo-qr-token"]')?.getAttribute('aria-hidden')
  }))
}, 1500)))()

